use num_bigint::BigInt;

/// Given a vector of mathematical integers, returns a new vector where each
/// element is the square of the corresponding input element.
pub fn square_elements(a: Vec<BigInt>) -> Vec<BigInt> {
    a.into_iter().map(|x| &x * &x).collect()
}

